1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Optional;
4	
5	import net.officefloor.plugin.variable.Out;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.escalation.IdempotentReplayException;
9	import org.springframework.samples.petclinic.rest.function.common.Lookups;
10	import org.springframework.samples.petclinic.rest.escalation.NotFoundException;
11	import org.springframework.samples.petclinic.rest.idempotency.IdempotencyStore;
12	import org.springframework.web.bind.annotation.RequestHeader;
13	
14	/**
15	 * First step of {@code POST /api/owners}. Reads the optional {@code Idempotency-Key} header and,
16	 * when it matches a create that already completed, short-circuits the pipeline by throwing
17	 * {@link IdempotentReplayException} so the original owner is returned with 200 rather than a
18	 * duplicate being created. Otherwise it publishes the key (or an {@link IdempotencyKey#absent()
19	 * absent} marker) for {@link RecordIdempotencyKey} to pin once the create succeeds.
20	 */
21	public class CheckIdempotencyKey {
22	
23	    public void service(
24	            @RequestHeader(name = "Idempotency-Key", required = false) String key,
25	            IdempotencyStore idempotencyStore, OwnerRepository ownerRepository,
26	            Out<IdempotencyKey> idempotencyKey)
27	            throws IdempotentReplayException, NotFoundException {
28	
29	        idempotencyKey.set(new IdempotencyKey(key));
30	
31	        if (key == null) {
32	            return; // no key: an ordinary create
33	        }
34	
35	        Optional<Integer> createdId = idempotencyStore.find(key);
36	        if (createdId.isPresent()) {
37	            Owner original = Lookups.findOrNotFound(() -> ownerRepository.findById(createdId.get()),
38	                    "Owner not found: " + createdId.get());
39	            throw new IdempotentReplayException(original);
40	        }
41	    }
42	}
