6	/**
7	 * Normalizes an owner's address to its canonical form (trimmed, whitespace collapsed, upper-cased,
8	 * abbreviations expanded) in place on the shared body, so the persisted and returned address is
9	 * that canonical string and every later address comparison sees it. Normalization applies to
10	 * whichever address fields the request supplied: the structured {@code addressLine1}/
11	 * {@code addressLine2} and the flat {@code address}.
12	 *
13	 * <p>The structured form is preferred: when {@code addressLine1} is present the {@code address} is
14	 * set to the {@link OwnerAddress#compose composed} lines, so the flat {@code address} always holds
15	 * the effective, normalized address; otherwise the supplied flat {@code address} is normalized in
16	 * place. It runs before validation, so an owner that supplies neither form is rejected there as a
17	 * missing required field. It mutates the already-published body variable rather than binding
18	 * {@code @RequestBody}, so it composes after the sole binding step in the pipeline.
19	 */
20	public class NormalizeOwnerAddress {
21	
22	    public void service(@Val OwnerFieldsDto request) {
23	        // Normalize each supplied structured line in place, leaving an absent line absent.
24	        if (request.getAddressLine1() != null) {
25	            request.setAddressLine1(OwnerAddress.normalize(request.getAddressLine1()));
26	        }
27	        if (request.getAddressLine2() != null) {
28	            request.setAddressLine2(OwnerAddress.normalize(request.getAddressLine2()));
29	        }
30	
31	        String addressLine1 = request.getAddressLine1();
32	        if (addressLine1 != null && !addressLine1.isBlank()) {
33	            // Structured form present: the effective address is the composed lines.
34	            request.setAddress(OwnerAddress.compose(addressLine1, request.getAddressLine2()));
35	        }
36	        else if (request.getAddress() != null) {
37	            // Flat form only: normalize it in place (absence is reported by validation).
38	            request.setAddress(OwnerAddress.normalize(request.getAddress()));
39	        }
40	    }
41	}
