2	
3	import java.util.ArrayList;
4	import java.util.LinkedHashMap;
5	import java.util.LinkedHashSet;
6	import java.util.Map;
7	import java.util.Set;
8	import java.util.function.Supplier;
9	
10	import jakarta.validation.ConstraintViolation;
11	import jakarta.validation.Validator;
12	import net.officefloor.plugin.variable.Out;
13	import net.officefloor.plugin.variable.Val;
14	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
15	import org.springframework.samples.petclinic.rest.escalation.InvalidOwnerFieldsException;
16	
17	/**
18	 * Runs after {@link NormalizeOwnerTelephone} in {@code POST /api/owners}. Rejects a body
19	 * that is missing or blank in any required field ({@code firstName}, {@code lastName},
20	 * {@code address}, {@code city}, {@code telephone}), and also applies the DTO's declared
21	 * format constraints. When any field is invalid it throws
22	 * {@link InvalidOwnerFieldsException} naming those fields, so the response is a 400
23	 * listing them; otherwise it publishes the validated body for the downstream build step.
24	 * It reads the already-normalized body as a variable rather than binding {@code @RequestBody}.
25	 */
26	public class ValidateOwnerFields {
27	
28	    /** Required fields in the order they should be reported, paired with their accessor. */
29	    private static Map<String, Supplier<String>> requiredFields(OwnerFieldsDto request) {
30	        Map<String, Supplier<String>> fields = new LinkedHashMap<>();
31	        fields.put("firstName", request::getFirstName);
32	        fields.put("lastName", request::getLastName);
33	        fields.put("address", request::getAddress);
34	        fields.put("city", request::getCity);
35	        fields.put("telephone", request::getTelephone);
36	        return fields;
37	    }
38	
39	    public void service(@Val OwnerFieldsDto request, Validator validator,
40	            Out<OwnerFieldsDto> validated) throws InvalidOwnerFieldsException {
41	
42	        // Preserve field-declaration order and de-duplicate fields flagged more than once.
43	        Set<String> invalid = new LinkedHashSet<>();
44	
45	        // Required fields must be present and non-blank.
46	        requiredFields(request).forEach((name, accessor) -> {
47	            String value = accessor.get();
48	            if (value == null || value.isBlank()) {
49	                invalid.add(name);
50	            }
51	        });
52	
53	        // Present fields must still satisfy the DTO's declared constraints (size, pattern, ...).
54	        for (ConstraintViolation<OwnerFieldsDto> violation : validator.validate(request)) {
55	            invalid.add(violation.getPropertyPath().toString());
56	        }
57	
58	        if (!invalid.isEmpty()) {
59	            throw new InvalidOwnerFieldsException(new ArrayList<>(invalid));
60	        }
61	
62	        validated.set(request);
63	    }
64	}
