3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerIdentityException;
8	
9	/**
10	 * Runs in {@code POST /api/owners} after {@link ValidateOwnerFields} (and after the email-domain
11	 * blocklist), reading the already-normalized body as a variable. Rejects a duplicate — an existing
12	 * owner with the same {@link OwnerIdentity#key identity key} (normalized telephone, lower-cased
13	 * email and {@code soundex(lastName)}) — with a 409, before any entity is built or persisted.
14	 *
15	 * <p>The identity key is the single duplicate criterion: because the telephone is part of it, two
16	 * owners with the same last name and postcode but different telephones have different keys and are
17	 * both allowed — the second is created and flagged downstream as a possible duplicate by
18	 * {@link AssignOwnerPossibleDuplicate}. A soft-deleted owner no longer holds its identity and is
19	 * ignored. Reads the same transaction as the writes.
20	 */
21	public class EnsureUniqueOwnerIdentity {
22	
23	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
24	            throws DuplicateOwnerIdentityException {
25	
26	        String identityKey = OwnerIdentity.key(request.getTelephone(), request.getEmail(), request.getLastName());
27	        for (Owner existing : ownerRepository.findAll()) {
28	            if (existing.isDeleted()) {
29	                continue; // a soft-deleted owner no longer holds its identity
30	            }
31	            String existingKey = OwnerIdentity.key(existing.getTelephone(), existing.getEmail(),
32	                    existing.getLastName());
33	            if (identityKey.equals(existingKey)) {
34	                throw new DuplicateOwnerIdentityException(identityKey);
35	            }
36	        }
37	    }
38	}
