3	import java.util.Comparator;
4	import java.util.Optional;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.util.Soundex;
11	
12	/**
13	 * Flags a soft duplicate: an owner whose {@link OwnerIdentity#key identity key} differs from every
14	 * existing owner (so it is not a hard duplicate, already rejected upstream) but which shares an
15	 * existing owner's {@code soundex(lastName)} and postcode. Records the match as
16	 * {@code possibleDuplicate} true with {@code possibleDuplicateOf} set to the matched owner's id,
17	 * else {@code possibleDuplicate} false. Runs before the new owner is persisted so it is not compared
18	 * against itself.
19	 *
20	 * <p>An owner that declared itself a household member with {@code sharesHousehold=true} is never
21	 * flagged: it is a known member of the household, not a suspected duplicate of it.
22	 */
23	public class AssignOwnerPossibleDuplicate {
24	
25	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
26	        Optional<Owner> match = softMatch(request, owner, ownerRepository);
27	        owner.setPossibleDuplicate(match.isPresent());
28	        owner.setPossibleDuplicateOf(match.map(Owner::getId).orElse(null));
29	    }
30	
31	    private static Optional<Owner> softMatch(OwnerFieldsDto request, Owner owner,
32	            OwnerRepository ownerRepository) {
33	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
34	            return Optional.empty(); // a declared household member is not a suspected duplicate
35	        }
36	        String postcode = owner.getPostcode();
37	        if (postcode == null || postcode.isBlank()) {
38	            return Optional.empty(); // a shared postcode is required to soft-match
39	        }
40	        String identityKey = OwnerIdentity.key(owner.getTelephone(), owner.getEmail(), owner.getLastName());
41	        String soundex = Soundex.encode(owner.getLastName());
42	        return ownerRepository.findAll().stream()
43	                .filter(existing -> !existing.isDeleted()) // a soft-deleted owner is not a duplicate match
44	                .filter(existing -> postcode.equals(existing.getPostcode()))
45	                .filter(existing -> soundex.equals(Soundex.encode(existing.getLastName())))
46	                .filter(existing -> !identityKey.equals(OwnerIdentity.key(existing.getTelephone(),
47	                        existing.getEmail(), existing.getLastName())))
48	                .min(Comparator.comparing(Owner::getId));
49	    }
50	}
