4	import org.springframework.samples.petclinic.util.Sha256;
5	import org.springframework.samples.petclinic.util.Soundex;
6	
7	/**
8	 * The derived duplicate-detection identity of an owner: a single SHA-256 key that consolidates the
9	 * telephone, email and phonetic last name the create pipeline rejects duplicates by. The key is the
10	 * SHA-256 hex digest of {@code 'V2' + '|' + normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)},
11	 * the leading version tag distinguishing it from the version-1 key.
12	 *
13	 * <p>Two owners are duplicates only when their <em>whole</em> keys are equal. Because the telephone
14	 * is part of the key, two owners with the same last name and postcode but different telephones have
15	 * different keys and are both allowed — only an exact full-key match is a duplicate.
16	 */
17	public final class OwnerIdentity {
18	
19	    private OwnerIdentity() {
20	    }
21	
22	    /**
23	     * The identity key for the given canonical components. The telephone is folded to its
24	     * {@link OwnerTelephone#toE164(String) E.164} form, the email to its
25	     * {@link OwnerEmail#normalize(String) lower-cased} form and the last name to its
26	     * {@link Soundex#encode(String) Soundex} code; an absent email or last name contributes the
27	     * empty string. The fixed {@link OwnerIdentityVersion#TAG version tag} is mixed in as the leading
28	     * component so a version-2 key can never repeat a version-1 one. The components are joined by
29	     * {@code '|'} and SHA-256 hex digested.
30	     */
31	    public static String key(String telephone, String email, String lastName) {
32	        String raw = OwnerIdentityVersion.TAG + "|" + normalizedTelephone(telephone) + "|"
33	                + normalizedEmail(email) + "|" + Soundex.encode(lastName);
34	        return Sha256.hex(raw);
35	    }
36	
37	    private static String normalizedTelephone(String telephone) {
38	        return OwnerTelephone.toE164(telephone).orElse(orEmpty(telephone));
39	    }
40	
41	    private static String normalizedEmail(String email) {
42	        return (email == null || email.isBlank()) ? "" : OwnerEmail.normalize(email);
43	    }
44	
45	    private static String orEmpty(String value) {
46	        return value == null ? "" : value;
47	    }
48	}
