1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.Set;
5	import java.util.regex.Pattern;
6	import java.util.stream.Collectors;
7	
8	/**
9	 * Email normalization shared by the owner pipelines: decides whether an address is
10	 * syntactically valid and produces its canonical (lower-cased) form, so an owner's
11	 * email is validated and stored in one consistent representation.
12	 */
13	public final class OwnerEmail {
14	
15	    /** A syntactically valid address: {@code local@domain.tld} with no whitespace. */
16	    private static final Pattern VALID = Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
17	
18	    /** Domains of throwaway/disposable mailboxes that owners may not register with. */
19	    private static final Set<String> DISPOSABLE_DOMAINS =
20	            Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
21	
22	    /** The distinctive service labels of the disposable domains ({@code mailinator},
23	     *  {@code tempmail}, {@code guerrillamail}) — the second-level name with the suffix
24	     *  stripped — used to recognise disposable-adjacent domains. */
25	    private static final Set<String> DISPOSABLE_LABELS = DISPOSABLE_DOMAINS.stream()
26	            .map(domain -> domain.substring(0, domain.indexOf('.')))
27	            .collect(Collectors.toUnmodifiableSet());
28	
29	    private OwnerEmail() {
30	    }
31	
32	    /** Whether {@code email} is a syntactically valid address. */
33	    public static boolean isValid(String email) {
34	        return email != null && VALID.matcher(email).matches();
35	    }
36	
37	    /** The canonical, lower-cased form of {@code email}. */
38	    public static String normalize(String email) {
39	        return email.toLowerCase(Locale.ROOT);
40	    }
41	
42	    /** Whether {@code email}'s domain is on the disposable-domain blocklist. */
43	    public static boolean isDisposable(String email) {
44	        String domain = domainOf(email);
45	        return domain != null && DISPOSABLE_DOMAINS.contains(domain);
46	    }
47	
48	    /**
49	     * Whether {@code email}'s domain is <em>disposable-adjacent</em>: it carries a known
50	     * throwaway-mail service's label ({@code mailinator}, {@code tempmail},
51	     * {@code guerrillamail}) as one of its dot-separated labels. This catches close
52	     * relatives of a blocklisted domain that slip past {@link #isDisposable} — a subdomain
53	     * of one ({@code x.mailinator.com}) or the same service under a different suffix
54	     * ({@code mailinator.net}) — so an owner whose exact-match disposable address would have
55	     * been refused at creation can still be flagged as risky.
56	     */
57	    public static boolean isDisposableAdjacent(String email) {
58	        String domain = domainOf(email);
59	        if (domain == null) {
60	            return false;
61	        }
62	        for (String label : domain.split("\\.")) {
63	            if (DISPOSABLE_LABELS.contains(label)) {
64	                return true;
65	            }
66	        }
67	        return false;
68	    }
69	
70	    /** The lower-cased domain part of {@code email}, or null when it carries no {@code '@'}. */
71	    private static String domainOf(String email) {
72	        if (email == null) {
73	            return null;
74	        }
75	        int at = email.lastIndexOf('@');
76	        return at < 0 ? null : email.substring(at + 1).toLowerCase(Locale.ROOT);
77	    }
78	}
