2	
3	import java.util.Locale;
4	
5	import org.springframework.samples.petclinic.util.OwnerIdentityVersion;
6	import org.springframework.samples.petclinic.util.Sha256;
7	
8	/**
9	 * Identity of an owner's household. Two owners live in the same household when they share the
10	 * same last name and postcode. The last name is compared case-insensitively with collapsed
11	 * whitespace and the postcode as supplied.
12	 *
13	 * <p>The {@link #id(String, String) household id} is derived deterministically from that
14	 * canonical key, so every owner with the same last name and postcode computes the same stable
15	 * identifier automatically — no owner has to opt in for the link to form.
16	 */
17	final class Household {
18	
19	    /** Number of leading hex characters of the digest that make up the household id. */
20	    private static final int ID_LENGTH = 12;
21	
22	    private Household() {
23	    }
24	
25	    /**
26	     * Canonical household key: the {@link OwnerIdentityVersion#TAG version tag} then the last name
27	     * trimmed, internal whitespace collapsed and lower-cased, joined to the postcode with
28	     * {@code '|'} so distinct pairs never collide. The version tag is mixed in so a version-2
29	     * household id can never repeat a version-1 one.
30	     */
31	    static String key(String lastName, String postcode) {
32	        return OwnerIdentityVersion.TAG + "|" + canonical(lastName) + "|" + orEmpty(postcode);
33	    }
34	
35	    /**
36	     * Stable identifier shared by every owner in the household: the first {@value #ID_LENGTH} hex
37	     * characters of the SHA-256 digest of the canonical {@link #key(String, String) key}, so any
38	     * two owners with the same last name and postcode derive the same value.
39	     */
40	    static String id(String lastName, String postcode) {
41	        return Sha256.hex(key(lastName, postcode)).substring(0, ID_LENGTH);
42	    }
43	
44	    /** Case-insensitive form with leading/trailing and repeated internal whitespace collapsed. */
45	    private static String canonical(String value) {
46	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
47	    }
48	
49	    private static String orEmpty(String value) {
50	        return value == null ? "" : value;
51	    }
52	}
