1	package org.springframework.samples.petclinic.util;
2	
3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	import java.util.Set;
6	
7	/**
8	 * Business-day helpers for the owner registration date.
9	 */
10	public final class BusinessDay {
11	
12	    /**
13	     * Fixed public holidays that are not treated as business days.
14	     */
15	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
16	            LocalDate.of(2026, 1, 1),
17	            LocalDate.of(2026, 1, 26),
18	            LocalDate.of(2026, 4, 25),
19	            LocalDate.of(2026, 12, 25),
20	            LocalDate.of(2026, 12, 28));
21	
22	    private BusinessDay() {
23	    }
24	
25	    /**
26	     * Rolls a date forward to the next business day: weekends (Saturday and Sunday) and listed
27	     * public holidays are skipped, so a date that lands on either advances to the following
28	     * non-weekend, non-holiday day, while a date already on a business day is returned unchanged.
29	     */
30	    public static LocalDate rollForward(LocalDate date) {
31	        LocalDate adjusted = date;
32	        while (!isBusinessDay(adjusted)) {
33	            adjusted = adjusted.plusDays(1);
34	        }
35	        return adjusted;
36	    }
37	
38	    private static boolean isBusinessDay(LocalDate date) {
39	        DayOfWeek day = date.getDayOfWeek();
40	        if (day == DayOfWeek.SATURDAY || day == DayOfWeek.SUNDAY) {
41	            return false;
42	        }
43	        return !PUBLIC_HOLIDAYS.contains(date);
44	    }
45	}
