5	/**
6	 * Fiscal-year helpers for owner date-derived values. The fiscal year starts on 1 July, so a date
7	 * on or after 1 July belongs to the fiscal year that ends the following calendar year, and a date
8	 * before 1 July belongs to the one ending in its own calendar year. A fiscal year is identified by
9	 * the calendar year in which it ends (the Australian convention: 1 July 2025 - 30 June 2026 is
10	 * 'FY26').
11	 */
12	public final class FiscalYear {
13	
14	    /** The month (1 July) on which each fiscal year starts. */
15	    private static final int FISCAL_YEAR_START_MONTH = 7;
16	
17	    private FiscalYear() {
18	    }
19	
20	    /**
21	     * The fiscal year the date falls in, identified by the calendar year in which it ends: the
22	     * date's own year before 1 July, or the next year on or after 1 July.
23	     */
24	    public static int of(LocalDate date) {
25	        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH ? date.getYear() + 1 : date.getYear();
26	    }
27	
28	    /** The fiscal year of {@code date} as 'FY<YY>' (e.g. 'FY26'), the last two digits of {@link #of}. */
29	    public static String label(LocalDate date) {
30	        return String.format("FY%02d", of(date) % 100);
31	    }
32	
33	    /**
34	     * The number of whole fiscal years elapsed from {@code from} to {@code to}, i.e. the count of
35	     * 1-July boundaries crossed between them. Zero when both dates fall in the same fiscal year.
36	     */
37	    public static long elapsed(LocalDate from, LocalDate to) {
38	        return (long) of(to) - of(from);
39	    }
40	}
