8	 * the 2-digit {@link FiscalYear fiscal year} FY, an 8-character hash HASH8 that identifies the
9	 * person, and a single {@link Luhn} check digit CHK. HASH8 is the first 8 upper-case hex characters
10	 * of {@code SHA-256(normalizedTelephone + lastName)} (the same hash the region-and-hash identity
11	 * uses), so the same person in the same region and fiscal year always resolves to the same id
12	 * without any sequence number (e.g. {@code 'NSW271A2B3C4D5'}). CHK is the Luhn check digit computed
13	 * over the digits of {@code <REGION><FY><HASH8>}.
14	 */
15	public final class MemberId {
16	
17	    private static final String SEPARATOR = "-";
18	
19	    /** Number of leading hex characters of the digest kept as HASH8. */
20	    private static final int HASH_LENGTH = 8;
21	
22	    /** Number of digits in the FY segment. */
23	    private static final int FISCAL_YEAR_LENGTH = 2;
24	
25	    /** Length of the fixed core following the region: {@code FY(2) + HASH8(8) + CHK(1)}. */
26	    private static final int CORE_SUFFIX_LENGTH = FISCAL_YEAR_LENGTH + HASH_LENGTH + 1;
27	
28	    private MemberId() {
29	    }
30	
31	    /**
32	     * The member id for the given {@code region} and {@code fiscalYear} (identified by the calendar
33	     * year it ends in, e.g. {@code 2027}), hashing the person's {@code normalizedTelephone} and
34	     * {@code lastName} into HASH8 and appending the Luhn check digit over the preceding digits.
35	     */
36	    public static String of(String region, int fiscalYear, String normalizedTelephone, String lastName) {
37	        String body = region + String.format("%02d", fiscalYear % 100)
