46	     */
47	    public static String deduplicate(String memberId, Set<String> taken) {
48	        if (!taken.contains(memberId)) {
49	            return memberId;
50	        }
51	        for (int n = 2; ; n++) {
52	            String candidate = memberId + SEPARATOR + n;
53	            if (!taken.contains(candidate)) {
54	                return candidate;
55	            }
56	        }
57	    }
58	
59	    /** The REGION segment of a member id (everything before the fixed {@code <FY><HASH8><CHK>} core). */
