3	/**
4	 * Luhn check-digit computation over the digits contained in a string. Non-digit
5	 * characters are ignored, so it works directly on formatted codes such as the
6	 * body of a member id ('NSW271A2B3C4D').
7	 */
8	public final class Luhn {
9	
10	    private Luhn() {
11	    }
12	
13	    /**
14	     * The Luhn check digit (0-9) computed over the digit characters of {@code s},
15	     * scanning right-to-left and doubling every other digit starting with the last.
16	     */
17	    public static int checkDigit(String s) {
18	        int sum = 0;
19	        boolean dbl = true;
20	        for (int i = s.length() - 1; i >= 0; i--) {
21	            char c = s.charAt(i);
22	            if (c < '0' || c > '9') {
23	                continue;
24	            }
25	            int d = c - '0';
26	            if (dbl) {
27	                d *= 2;
28	                if (d > 9) {
29	                    d -= 9;
30	                }
31	            }
32	            sum += d;
33	            dbl = !dbl;
34	        }
35	        return (10 - (sum % 10)) % 10;
36	    }
37	}
