3	/**
4	 * American Soundex phonetic encoding of a name: the first letter followed by three digits that
5	 * fold together consonants sharing a sound, so surnames that sound alike encode alike
6	 * (e.g. {@code Robert} and {@code Rupert} both encode {@code R163}). Used by the owner pipeline
7	 * so its identity and soft-match logic compare last names phonetically rather than literally.
8	 */
9	public final class Soundex {
10	
11	    private Soundex() {
12	    }
13	
14	    /**
15	     * The four-character Soundex code of {@code value} (retained first letter plus three digits,
16	     * zero-padded and truncated to length four). Non-letters are ignored; a value with no letters
17	     * (including {@code null}) encodes to the empty string. Letters separated by {@code h}/{@code w}
18	     * keep a shared code, letters separated by a vowel are coded twice.
19	     */
20	    public static String encode(String value) {
21	        if (value == null) {
22	            return "";
23	        }
24	        StringBuilder letters = new StringBuilder();
25	        for (int i = 0; i < value.length(); i++) {
26	            char c = value.charAt(i);
27	            if (Character.isLetter(c)) {
28	                letters.append(Character.toUpperCase(c));
29	            }
30	        }
31	        if (letters.length() == 0) {
32	            return "";
33	        }
34	        StringBuilder code = new StringBuilder().append(letters.charAt(0));
35	        char previous = codeOf(letters.charAt(0));
36	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
37	            char c = letters.charAt(i);
38	            if (c == 'H' || c == 'W') {
39	                continue; // does not break a run of same-coded consonants, nor reset the run
40	            }
41	            char digit = codeOf(c);
42	            if (digit != '0' && digit != previous) {
43	                code.append(digit);
44	            }
45	            previous = digit; // a vowel (digit '0') resets the run so a repeat is coded again
46	        }
47	        while (code.length() < 4) {
48	            code.append('0');
49	        }
50	        return code.toString();
51	    }
52	
53	    /** The Soundex digit for an upper-case letter, {@code '0'} for a vowel or uncoded letter. */
54	    private static char codeOf(char c) {
55	        switch (c) {
56	            case 'B': case 'F': case 'P': case 'V':
57	                return '1';
58	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
59	                return '2';
60	            case 'D': case 'T':
61	                return '3';
62	            case 'L':
63	                return '4';
64	            case 'M': case 'N':
65	                return '5';
66	            case 'R':
67	                return '6';
68	            default:
69	                return '0';
70	        }
71	    }
72	}
